package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class LayerDrawable extends Drawable implements Drawable.Callback { protected Drawable[] layers; private int[] ids; public LayerDrawable(Drawable[] d){layers=d;ids=new int[d.length];for(int i=0;i<d.length;i++)if(d[i]!=null)d[i].setCallback(this);} public int getNumberOfLayers(){return layers.length;} public Drawable getDrawable(int i){return layers[i];} public int getId(int i){return ids[i];} public void setId(int i,int id){ids[i]=id;} public Drawable findDrawableByLayerId(int id){for(int i=layers.length-1;i>=0;i--)if(ids[i]==id)return layers[i];return null;} public void draw(Canvas c){for(Drawable d:layers)if(d!=null)d.draw(c);} protected void onBoundsChange(Rect r){for(Drawable d:layers)if(d!=null)d.setBounds(r);} protected boolean onStateChange(int[] s){boolean b=false;for(Drawable d:layers)if(d!=null)b=d.setState(s)||b;return b;} protected boolean onLevelChange(int l){boolean b=false;for(Drawable d:layers)if(d!=null)b=d.setLevel(l)||b;return b;} public void invalidateDrawable(Drawable d){invalidateSelf();} public void scheduleDrawable(Drawable d,Runnable r,long t){scheduleSelf(r,t);} public void unscheduleDrawable(Drawable d,Runnable r){unscheduleSelf(r);}  public int getLayerGravity(int i){return 0;} public void setLayerGravity(int i,int v){} public int getLayerHeight(int i){return 0;} public void setLayerHeight(int i,int v){} public int getLayerInsetBottom(int i){return 0;} public void setLayerInsetBottom(int i,int v){} public int getLayerInsetEnd(int i){return 0;} public void setLayerInsetEnd(int i,int v){} public int getLayerInsetLeft(int i){return 0;} public void setLayerInsetLeft(int i,int v){} public int getLayerInsetRight(int i){return 0;} public void setLayerInsetRight(int i,int v){} public int getLayerInsetStart(int i){return 0;} public void setLayerInsetStart(int i,int v){} public int getLayerInsetTop(int i){return 0;} public void setLayerInsetTop(int i,int v){} public int getLayerWidth(int i){return 0;} public void setLayerWidth(int i,int v){} public void setLayerSize(int i,int w,int h){setLayerWidth(i,w);setLayerHeight(i,h);} }